local config = {
  ui_story_31110101_1_dialog_content = "Todo empezó un día en que estaba en el café ordenando los libros en las estanterías.",
  ui_story_31110101_2_dialog_content = "Después de la apertura del café, se ha convertido en el lugar número uno de diversión y relajación para mucha gente.",
  ui_story_31110101_3_dialog_content = "Y no sólo por el estupendo café que se toma, sino porque mucha gente se siente atraída por lo que se ofrece en las estanterías.",
