  ui_story_31110101_5_dialog_content = "Déjame ver... El Territorio Secreto Perdido debería ir ahí.",
  ui_story_31110101_6_dialog_content = "Y las Notas del Mercenario Sin Nombre... Debería ir en la sección \"Biografía\", en el estante inferior.",
  ui_story_31110101_7_dialog_content = "Directrices sociales de Illumina... debería ir en la parte superior, en la sección \"Sociedad\".",
  ui_story_31110101_8_dialog_content = "No lo puedo alcanzar. ¡Luciérnaga! ¿Un poco de ayuda?",
  ui_story_31110101_9_dialog_content = "“¿Necesitas ayuda? ¡Déjame ayudarte!”",
  ui_story_31110101_10_dialog_content = "Espera... ¿Por qué estás <color=#FFB400>reproduciendo la voz de Vice</color>? ¿Cuándo lo has grabado?",
  ui_story_31110101_11_dialog_content = "“Sólo déjamelos a mí. ¡Yo me encargaré de todo!”",
  ui_story_31110101_12_dialog_content = "\"¡Sería genial si pudieras ayudarme, sin embargo!”",
  ui_story_31110101_13_dialog_content = "<anim type=Shake><size=45>\"¡Sin embargo, sería genial si pudieras ayudarme!\"</size></anim>",
  ui_story_31110101_14_dialog_content = "¡Te he oído la primera vez!",
  ui_story_31110101_15_dialog_content = "Sólo tienes que ayudarme a poner las Directrices Sociales de Illumina ahí arriba, ¡y yo me encargo del resto!",
  ui_story_31110101_16_dialog_content = "Después de añadir estas nuevas características, las Luciérnagas han empezado a ser un poco demasiado inteligentes.",
  ui_story_31110101_17_dialog_content = "Y ahora... Geográfica Northland.",
  ui_story_31110101_18_dialog_content = "¿Ah?",
  ui_story_31110101_19_dialog_content = "<color=#e8d9bb>Cristales diminutos se extienden por la hermosa cubierta del libro.</color>",
  ui_story_31110101_20_dialog_content = "¿Cristales?",
  ui_story_31110101_21_dialog_content = "No es sólo este libro, ¡también están por todo el Viaje de un Aventurero y La Expedición Aurora!",
