  ui_story_31110101_23_dialog_content = "¿Qué pasa acá...?",
  ui_story_31110101_24_dialog_content = "Discúlpame.",
  ui_story_31110101_25_dialog_content = "Oh, PlayerName...",
  ui_story_31110101_26_dialog_content = "Oye, Beryl....¿Estás aquí para pedir prestados algunos libros?",
  ui_story_31110101_27_dialog_content = "Tengo que devolver un libro... Este...",
  ui_story_31110101_28_dialog_content = "¿<color=#FFB400>Receta Rediesel</color>?",
  ui_story_31110101_29_option_content = "No lo he leído aún.",
  ui_story_31110101_30_dialog_content = "¿Cómo era?",
  ui_story_31110101_31_dialog_content = "Es...",
  ui_story_31110101_32_dialog_content = "Es un libro sobre la cocina del Desierto de Rediesel.",
  ui_story_31110101_33_dialog_content = "Eso parece bastante claro.",
  ui_story_31110101_34_dialog_content = "...",
  ui_story_31110101_35_dialog_content = "¡Es mucho más que eso!",
  ui_story_31110101_36_dialog_content = "La Receta Rediesel presenta todo tipo de alimentos únicos...",
  ui_story_31110101_37_dialog_content = "Pero también es sobre el autor, el Tío Johnny, y su vida... Su filosofía... Es...",
  ui_story_31110101_X37_dialog_content = "<size=30>Un libro realmente sorprendente...</size>",
  ui_story_31110101_38_option_content = "Recuerdo este libro...",
  ui_story_31110101_39_dialog_content = "El autor dice ser un viajero a tiempo parcial y un comedor a tiempo completo, el Iron Chef del Desierto de Rediesel.",
  ui_story_31110101_40_dialog_content = "Se llama Tío Johnny, ¿no?",
  ui_story_31110101_41_dialog_content = "Hmm...<size=30>No pensé que lo hubieras leído, PlayerName.</size>",
  ui_story_31110101_42_dialog_content = "Sí, al fin y al cabo, esa receta de arroz con arena está para morirse.",
  ui_story_31110101_43_dialog_content = "Pero utiliza un lenguaje tan gráfico... No creo que sea realmente adecuado para los lectores más jóvenes.",
  ui_story_31110101_44_dialog_content = "Pero... Este libro tiene definitivamente mucha pasión en sus páginas... Sí.",
  ui_story_31110101_45_dialog_content = "Los camellos del desierto... y el mar brillante... Es todo tan romántico.",
  ui_story_31110101_46_dialog_content = "(No sabía que Beryl pudiera abrirse tanto cuando habla de libros...)",
  ui_story_31110101_47_dialog_content = "(Es completamente diferente de su habitual ser silencioso.)",
  ui_story_31110101_48_dialog_content = "Lo pondré de nuevo en el estante para ti. Hay algo más que desees leer...",
  ui_story_31110101_49_dialog_content = "Espera...¡El reverso de este libro está cubierto de cristales!",
  ui_story_31110101_50_dialog_content = "Parece que incluso forman una especie de... ¿imagen? Parece una cabeza... Es ese... ¿Tío Johnny?",
  ui_story_31110101_51_dialog_content = "¡Beryl!¿Eres tú el que ha estado cubriendo estos libros con cristales?",
  ui_story_31110101_52_dialog_content = "Lo siento...",
  ui_story_31110101_53_dialog_content = "He estado montando un <color=#FFB400>club de lectura</color> recientemente, así que... He tomado prestados un montón de libros del Colossus.",
  ui_story_31110101_54_dialog_content = "A veces pierdo el control... Cuando veo algo que me fascina... los cristales empiezan a crecer por todas las páginas.",
  ui_story_31110101_56_dialog_content = "Pero... No te preocupes. Puedo deshacerme de ellos.",
  ui_story_31110101_X56_dialog_content = "Aquí.",
  ui_story_31110101_57_dialog_content = "Solo necesito concentrarme...",
  ui_story_31110101_58_dialog_content = "¡En verdad se fueron! Entonces volveré a poner el libro en la estantería.",
  ui_story_31110101_59_dialog_content = "Por cierto, ¿hay algo más que te guste, además de este libro?",
  ui_story_31110101_60_dialog_content = "Si...",
  ui_story_31110101_61_dialog_content = "Si tienes tiempo, te recomiendo que leas Fábulas de Astra.",
  ui_story_31110101_62_dialog_content = "¿Es como una colección de diferentes historias? No lo he leído aún.",
  ui_story_31110101_63_dialog_content = "Sí, hay muchos cuentos filosóficos en él.",
  ui_story_31110101_64_dialog_content = "Como éste: La flor blanca.",
  ui_story_31110101_65_dialog_content = "\"Una flor extendió sus pétalos para mostrar al mundo su pureza.\"",
  ui_story_31110101_66_dialog_content = "\"Ya sea bañada en pigmento blanco o limpiada con rocío...”",
  ui_story_31110101_67_dialog_content = "\"No había forma de demostrar que su blanco era el más verdadero.\"",
  ui_story_31110101_68_dialog_content = "(¡La voz de Beryl es tan hermosa cuando lee!)",
  ui_story_31110101_69_dialog_content = "(¿Qué hacen esas Luciérnagas aquí? ¿Están secretamente <color=#FFB400>grabándonos</color>?)",
  ui_story_31110101_70_dialog_content = "\"Pero cuando estaba atrapado en la tierra, cuando estaba completamente cubierto con la tierra más negra.\"",
  ui_story_31110101_71_dialog_content = "\"Sólo entonces otros la alabaron por su pureza.\"",
  ui_story_31110101_72_dialog_content = "Aunque las historias son ficticias, reflejan la naturaleza de la realidad, y siempre me hacen pensar mucho.",
  ui_story_31110101_73_dialog_content = "Esta historia de la flor... Es como la historia de mis padres...",
  ui_story_31110101_74_dialog_content = "¿Tus padres?",
  ui_story_31110101_75_dialog_content = "Mmm...",
  ui_story_31110101_76_dialog_content = "Intento olvidar esos momentos cada día, pero...",
  ui_story_31110101_77_dialog_content = "Mis padres fueron incriminados. Para probar su inocencia, y para salvarme de convertirme en un sujeto de prueba...",
  ui_story_31110101_78_dialog_content = "Fueron a Umbraton para luchar contra los Eclipsites atraídos por los Cristales Sanguinarios, a pesar de la prohibición impuesta por la nobleza de Lumopolis.",
  ui_story_31110101_79_dialog_content = "Al final, fueron enterrados... Y yo...",
  ui_story_31110101_80_dialog_content = "El Cristal Sanguinario contaminado por Darkflow es como una pesadilla.",
  ui_story_31110101_81_dialog_content = "Cómo deseo que esta pesadilla termine y desaparezca de mi memoria para siempre..",
  ui_story_31110101_82_option_content = "Beryl...",
  ui_story_31110101_83_dialog_content = "Beryl...",
  ui_story_31110101_84_dialog_content = "¿Ah?¿Quién estaba llamando mi nombre como PlayerName?",
  ui_story_31110101_85_dialog_content = "Son las Luciérnagas. Se han actualizado con una función de grabación recientemente, y de vez en cuando reproducen el audio que han grabado...",
  ui_story_31110101_86_dialog_content = "¿Me han grabado hablando ahora mismo...?",
  ui_story_31110101_87_dialog_content = "\"Una flor extendió sus pétalos para mostrar al mundo su pureza.\"",
  ui_story_31110101_88_dialog_content = "\"Sólo entonces otros la alabaron por su pureza.\"",
  ui_story_31110101_89_dialog_content = "\"Esta historia de las flores... Es como la historia de mis padres...”",
  ui_story_31110101_X89_dialog_content = "...",
  ui_story_31110101_90_dialog_content = "Lo sabía... Mis pecados nunca serán borrados de este mundo.",
  ui_story_31110101_91_dialog_content = "¿Nunca se me permitirá vivir en paz?",
  ui_story_31110101_92_dialog_content = "\"Beryl... Nunca escaparás.\"",
  ui_story_31110101_93_dialog_content = "Esa pesadilla...",
  ui_story_31110101_94_dialog_content = "<size=45>¡Ahhh!</size>",
  ui_story_31110101_95_dialog_content = "Espera un segundo,¡Beryl! ¡Los Cristales!",
  ui_story_31110101_96_dialog_content = "¡Hay cristales por todas partes!¡Van a llenar todo el Café!",
  ui_story_31110101_97_dialog_content = "¡Cálmate, Beryl!",
  ui_story_31110101_98_dialog_content = "Casi pensé que acabaría enterrada viva por los cristales...",
  ui_story_31110101_99_dialog_content = "Lo siento, PlayerName. No debería haberme emocionado tanto.",
  ui_story_31110101_100_dialog_content = "Esas grabaciones de voz me trajeron malos recuerdos.",
  ui_story_31110101_101_dialog_content = "Soy yo quien debería disculparme. No quise grabar lo que has dicho. Fueron esas malditas luciérnagas...",
  ui_story_31110101_102_dialog_content = "¿Ah?",
  ui_story_31110101_103_dialog_content = "Verás, le pedí a Fleur que añadiera una función de grabación a las Luciérnagas.",
  ui_story_31110101_104_dialog_content = "Antes de que terminara, Genevieve apareció de repente y le dijo que sólo debían grabarse las \"citas dignas\".",
  ui_story_31110101_105_dialog_content = "Luego apareció Bonacie y dijo que sólo debían grabarse los sonidos que fueran agradables al oído.",
  ui_story_31110101_106_dialog_content = "Y entonces apareció Eicy para decir que quería que las grabaciones de las Luciérnagas fueran más humanas...",
  ui_story_31110101_107_dialog_content = "Ya sabes que Fleur siempre intenta complacer a todo el mundo, así que, por supuesto, prometió añadir todo lo que le pidieran. Y así, terminaron así...",
  ui_story_31110101_108_dialog_content = "Así que...¿<size=30>Eso es todo</size>?",
  ui_story_31110101_109_dialog_content = "Pero no te preocupes, todo lo que no quieras que oigan los demás se puede borrar.",
  ui_story_31110101_110_dialog_content = "¿Así que, qué piensas?",
  ui_story_31110101_111_dialog_content = "\"Descansa un poco.\"",
  ui_story_31110101_112_dialog_content = "Eso es lo que Carleen siempre dice.",
  ui_story_31110101_113_dialog_content = "Beryl, he sido perseguida por mis propias pesadillas, y sé lo terrible que puede ser...",
  ui_story_31110101_114_dialog_content = "Pero no hay necesidad de presionarse tanto. Creo que el tiempo cura todas las heridas.",
  ui_story_31110101_115_dialog_content = "¡Y tienes todos estos libros para leer! ¡Siempre habrá respuestas esperándote en sus páginas!",
  ui_story_31110101_116_dialog_content = "Realmente siento que, cuando toco estos libros, mi corazón se calma.",
  ui_story_31110101_117_dialog_content = "Gracias, PlayerName.",
  ui_story_31110101_118_dialog_content = "Oh sí, debería devolverte este libro. Aquí tienes...",
  ui_story_31110101_119_dialog_content = "¿Hmm? Hay algunos cristales en el...",
  ui_story_31110101_120_dialog_content = "Enfócate...",
  ui_story_31110101_121_dialog_content = "¿Ah?¿Por qué no puedo deshacerme de los cristales de este libro?",
  ui_story_31110101_122_dialog_content = "<size=30>¿Son estos cristales realmente una maldición imperdonable?</size>",
  ui_story_31110101_123_dialog_content = "No te preocupes por eso.",
  ui_story_31110101_124_dialog_content = "¿Ah?",
  ui_story_31110101_125_dialog_content = "Si no puedes deshacerte de ellos, déjalos ahí. ¡Estos cristales son como tus notas personales!",
  ui_story_31110101_126_dialog_content = "Dondequiera que encuentres un montón de cristales, ¡sabes que esta parte viene muy recomendada por Beryl! ¡Incluso hará que la gente preste más atención a tus páginas favoritas!",
  ui_story_31110101_127_dialog_content = "¡Problema resuelto!",
  ui_story_31110101_128_dialog_content = "PlayerName...",
  ui_story_31110101_129_dialog_content = "Así que, Beryl...¿Qué más te gustaría leer?",
  ui_story_31110101_130_dialog_content = "Pronto me iré a Umbraton para conseguir más libros y mantener las estanterías llenas de una colección aún más maravillosa.",
  ui_story_31110101_131_dialog_content = "Si ese es el caso, entonces quiero <color=#FFB400><size=30>La Niña</size></color>...",
  ui_story_31110101_132_dialog_content = "¿<color=#FFB400>La Niña</color>?",
  ui_story_31110101_133_dialog_content = "No. Adiós hagas caso, PlayerName.",
  ui_story_31110101_134_dialog_content = "¿Qué es ese libro de \"La Niña\" que mencionó?",
  ui_story_31110101_135_dialog_content = "Que la Verdad te bendiga, mi querido PlayerName.",
  ui_story_31110101_136_dialog_content = "¿También está aquí para devolver un libro?",
  ui_story_31110101_137_dialog_content = "Así es, estoy devolviendo el Pacto del Sueño.",
  ui_story_31110101_138_dialog_content = "El lunático sólo había visto un atisbo de la verdad, pensando que era el cuadro completo.",
  ui_story_31110101_139_dialog_content = "¿Pero cómo puede la dirección equivocada llevar a la conclusión correcta? Todo es una tontería imaginaria, por supuesto.",
  ui_story_31110101_140_dialog_content = "Pero no está mal si buscas un poco de entretenimiento ligero.",
  ui_story_31110101_141_dialog_content = "No tengo idea de lo que estás hablando.",
  ui_story_31110101_142_dialog_content = "Sólo mis pensamientos sobre el libro. ¡Ahora, como estabas!",
  ui_story_31110101_143_dialog_content = "¡Espera, Faust!",
  ui_story_31110101_144_dialog_content = "Has leído muchos libros en tu vida... ¿Por casualidad conoces un libro llamado \"La Niña\"?",
  ui_story_31110101_145_dialog_content = "¿\"La Niña\", dices?",
  ui_story_31110101_146_dialog_content = "¡Jajaja! Es realmente un placer escuchar tales palabras saliendo de tu boca, PlayerName.",
  ui_story_31110101_147_dialog_content = "Claro que lo sé.",
  ui_story_31110101_148_dialog_content = "Es una mentira dulce y romántica: palabras afiladas, escritas con tinta persistente.",
  ui_story_31110101_149_dialog_content = "Un sabor muy adecuado para las jóvenes, naturalmente.",
  ui_story_31110101_150_option_content = "¿Puedes parar con las adivinanzas?",
  ui_story_31110101_151_dialog_content = "¿Estamos hablando el mismo idioma?",
  ui_story_31110101_152_dialog_content = "¿Puedes cortarlo con las adivinanzas?",
  ui_story_31110101_153_option_content = "¡Sí, entiendo!",
  ui_story_31110101_154_dialog_content = "¡Es una historia de amor!",
  ui_story_31110101_155_dialog_content = "También deberías leer más libros de ese tipo, PlayerName.",
  ui_story_31110101_156_dialog_content = "Sólo entonces entenderás los sentimientos de una chica que parece indiferente a primera vista, pero que es amable en el fondo.",
  ui_story_31110601_1_dialog_content = "<color=#e8d9bb>Informe, actividad anormal de nubes y aumento de temperatura del aire detectado. Alta probabilidad de lluvia.</color>",
  ui_story_31110601_2_dialog_content = "(Mi corazón esta palpitando...)",
  ui_story_31110601_3_dialog_content = "(Quiero respirar, pero siento como si un peso me aplastara el pecho. Es sofocante...)",
  ui_story_31110601_4_dialog_content = "Apúrate...",
  ui_story_31110601_5_dialog_content = "(¿Alguien me está llamando...?)",
  ui_story_31110601_6_dialog_content = "(¿Estoy empezando a alucinar? Quizás debería cerrar los ojos ...)",
  ui_story_31110601_7_dialog_content = "¡Despierta, PlayerName! ¡Abre tus ojos!",
  ui_story_31110601_8_dialog_content = "¿B... Beryl?",
  ui_story_31110601_9_dialog_content = "¡Finalmente estás despierto! Gracias a Dios estás bien...",
  ui_story_31110601_10_dialog_content = "¿Podrías... *Tose* Podrías por favor... soltarme? No puedo respirar...",
  ui_story_31110601_11_dialog_content = "<size=30>¡Lo siento...!</size> ¿Puedes pararte?",
  ui_story_31110601_12_dialog_content = "Creo que sí.",
  ui_story_31110601_13_dialog_content = "Vaya... Mucho mejor. Gracias por sacarme del mar.",
  ui_story_31110601_14_dialog_content = "Realmente me diste un susto justo ahora...",
  ui_story_31110601_15_dialog_content = "Corriste hacia mí, pero luego las olas te arrastraron...",
  ui_story_31110601_16_dialog_content = "E-Eso es porque...",
  ui_story_31110601_17_dialog_content = "(Fue porque la noté nadando allí).",
  ui_story_31110601_18_dialog_content = "(Pero luego, de repente, desapareció bajo la superficie. Pensé que se estaba ahogando...)",
  ui_story_31110601_19_dialog_content = "(Así que justo cuando me abalancé para salvarla, una ola me golpeó en la cara y me derribó).",
  ui_story_31110601_20_dialog_content = "(......)",
  ui_story_31110601_21_dialog_content = "(Creo que es hora de hacer algo con este mal hábito mío).",
  ui_story_31110601_23_dialog_content = "Lo siento...",
  ui_story_31110601_24_dialog_content = "¿Qué hacias en el mar, de todos modos? ¿Por qué no está Raphaela contigo?",
  ui_story_31110601_25_dialog_content = "Rompí mi pala de juguete cuando estábamos haciendo un castillo de arena, así que fue a buscar una nueva...",
  ui_story_31110601_26_dialog_content = "¿Ustedes dos hacian un castillo de arena?",
  ui_story_31110601_27_dialog_content = "¡Sí! El verano casi ha terminado y pronto dejaremos este lugar.",
  ui_story_31110601_28_dialog_content = "¡Antes de hacerlo, quiero intentar lo mejor que pueda para hacer un castillo de arena más grande y hermoso!",
  ui_story_31110601_29_dialog_content = "Como una última celebración para el verano...",
  ui_story_31110601_30_dialog_content = "Encontré una concha realmente bonita para decorar el castillo de arena, pero se lavó al mar...",
  ui_story_31110601_31_dialog_content = "Así que fui a buscarlo.",
  ui_story_31110601_32_dialog_content = "Probablemente sea demasiado tarde ahora, ¿no?",
  ui_story_31110601_33_dialog_content = "Rescatarme debe haberte hecho perder de vista, ¿verdad? ¿Qué tipo de concha era?",
  ui_story_31110601_34_dialog_content = "Era una gran concha plateada con estas líneas realmente hermosas. Es más grande que la mayoría de las conchas de la playa.",
  ui_story_31110601_35_dialog_content = "¡Entiendo! Asumiré la responsabilidad ayudándote a encontrar otra concha para tu castillo de arena, ¿de acuerdo?",
  ui_story_31110601_36_dialog_content = "¡E-está bien ...! ¡Gracias, PlayerName! ¡Estaré esperando en mi castillo de arena!",
  ui_story_31110601_37_dialog_content = "<color=#e8d9bb>Algún tiempo después...</color>",
  ui_story_31110601_38_dialog_content = "¡Volví!",
  ui_story_31110601_39_dialog_content = "¡Bienvenido de nuevo, PlayerName! Espero que no hayas tenido muchos problemas.",
  ui_story_31110601_40_dialog_content = "Este es el castillo de arena que construimos hoy. <size=30>Solo le estoy dando algunos toques adicionales.</size>",
  ui_story_31110601_41_dialog_content = "Esto es... ¿un castillo de arena?",
  ui_story_31110601_42_dialog_content = "Desde abajo parece uno, pero el detalle puesto en las ventanas y puertas es demasiado...",
  ui_story_31110601_43_dialog_content = "Incluso hay una doncella en la torre más alta...",
  ui_story_31110601_44_dialog_content = "Sus alas están perfectamente diseñadas y cada pluma es distinta.",
  ui_story_31110601_46_dialog_content = "Es una obra maestra... No puedo evitar preguntarme si las esculturas de Lumopolis eran también obras de Beryl...",
  ui_story_31110601_47_dialog_content = "¿PlayerName?",
  ui_story_31110601_48_dialog_content = "Ejem, quiero decir, ¡estas conchas son decoraciones perfectas para tu castillo de arena!",
  ui_story_31110601_49_dialog_content = "Además, estos cristales... ¿Podrían ser...?",
  ui_story_31110601_50_dialog_content = "Sí... verás, he estado practicando el control de mi poder últimamente.",
  ui_story_31110601_51_dialog_content = "Antes, solo usaba mi poder para True Order.",
  ui_story_31110601_52_dialog_content = "Pero ahora, me doy cuenta de que no es solo algo aterrador. También... puede ser hermoso.",
  ui_story_31110601_53_dialog_content = "Se siente raro decirlo, pero desde ese día, siento como si me hubieran quitado una pesada carga...",
  ui_story_31110601_54_dialog_content = "Mi corazón se siente ligero ahora.",
  ui_story_31110601_55_dialog_content = "Es genial escuchar eso, Beryl.",
  ui_story_31110601_56_dialog_content = "Creo que tengo algo más que te hará aún más feliz.",
  ui_story_31110601_57_dialog_content = "¡Toma, concha nueva!",
  ui_story_31110601_58_dialog_content = "Me tomó un tiempo encontrar una allí. Este es la más grande que pude encontrar.",
  ui_story_31110601_59_dialog_content = "¡Es incluso mejor que la que encontré antes!",
  ui_story_31110601_60_dialog_content = "Ahora para ponerla en su lugar...",
  ui_story_31110601_61_dialog_content = "Es una pena que tengamos que dejar algo tan hermoso aquí en la playa.",
  ui_story_31110601_62_dialog_content = "Lo único que podemos hacer es dejarla a merced del sol y el viento.",
  ui_story_31110601_63_dialog_content = "El aire también está un poco cargado hoy. Hay muchas posibilidades de que llueva.",
  ui_story_31110601_64_dialog_content = "Y cuando suba la marea, eventualmente se llevará todo...",
  ui_story_31110601_65_dialog_content = "Si tan solo hubiera una manera de ponerlo en el Colossus...",
  ui_story_31110601_66_dialog_content = "Algo tan grande... No sería fácil de hacer... ¿verdad?",
  ui_story_31110601_67_dialog_content = "(No creo que ni siquiera quepa por la puerta del Colossus).",
  ui_story_31110601_68_dialog_content = "... ¡Está bien! Incluso si no podemos llevarlo con nosotros...",
  ui_story_31110601_69_dialog_content = "¡Siempre podemos volver el año que viene para construir uno nuevo!",
  ui_story_31110601_70_dialog_content = "Y el año siguiente, y todos los años posteriores... Siempre que sea lo que quieras, Beryl, podemos volver todos los años.",
  ui_story_31110601_71_dialog_content = "¡Regresé, Beryl!",
  ui_story_31110601_72_dialog_content = "¿Ves? ¡Te traje un balde nuevo, así como una pala y un pico nuevos!",
  ui_story_31110601_73_dialog_content = "¿Oh? ¡PlayerName! ¿También estás aquí para construir un castillo de arena?",
  ui_story_31110601_74_dialog_content = "Es un arte, ¿sabes? No es diferente de pintar o esculpir.",
  ui_story_31110601_75_dialog_content = "¿Estás seguro de que tienes ese tipo de habilidad, PlayerName...?",
  ui_story_31110601_76_dialog_content = "¡Oye! ¡¿Cómo puedes decir eso cuando no has visto mi obra de arte?!",
  ui_story_31110601_77_dialog_content = "Oh, sé mucho sobre tu arte. Vice me lo ha contado todo...",
  ui_story_31110601_78_dialog_content = "Aquí está la verdad, Beryl.",
  ui_story_31110601_79_dialog_content = "¡Vice una vez describió los bigotes del gato en el dibujo de PlayerName como tentáculos de un pulpo!",
  ui_story_31110601_80_dialog_content = "¡Tú...! Yo...",
  ui_story_31110601_81_dialog_content = "De todos modos, ¿de qué hablaban ustedes dos hace un momento?",
  ui_story_31110601_82_dialog_content = "Estábamos pensando en una forma de llevarnos el castillo de arena...",
  ui_story_31110601_83_dialog_content = "Entonces, Raphaela la más brillante e inteligente. ¿Tienes alguna idea?",
  ui_story_31110601_84_dialog_content = "Oh, realmente sabes cómo poner mantequilla a alguien antes de pedir algo, ¿verdad Beryl? Bueno, no te equivocas, ¡soy inteligente!",
  ui_story_31110601_85_dialog_content = "Pensaré en algo, ¡así que no te preocupes más por tu linda cabecita!",
  ui_story_31110601_86_dialog_content = "......",
  ui_story_31110601_87_dialog_content = "No tienes ni idea, ¿verdad...?",
  ui_story_31110601_88_dialog_content = "¡Cállate! ¿No ves que estoy tratando de pensar aquí?",
  ui_story_31110601_89_dialog_content = "Veamos... ¿Podríamos confiar a la Unión de Mensajería para dividirla y ayudarnos a cumplir?",
  ui_story_31110601_90_dialog_content = "Eso suena aún más difícil que simplemente reconstruirlo en el Colossus...",
  ui_story_31110601_91_dialog_content = "Entonces... ¿y si construimos el castillo de arena en lo alto del cielo, como un hito?",
  ui_story_31110601_92_dialog_content = "De esa manera, podemos verlo desde donde estemos, ¡tú tampoco tendrías que llevarlo contigo!",
  ui_story_31110601_93_dialog_content = "Incluso si usamos cada grano de arena en esta playa, estoy bastante seguro de que aún no podríamos hacerlo tan grande...",
  ui_story_31110601_94_dialog_content = "Siempre podríamos congelarlo...",
  ui_story_31110601_95_dialog_content = "Sin embargo, eso no evitará que el sol y la lluvia lo desgasten.",
  ui_story_31110601_96_dialog_content = "Aún así, el hielo aún se puede derretir.",
  ui_story_31110601_97_dialog_content = "En ese caso, no tenemos más remedio que utilizar nuestro último recurso.",
  ui_story_31110601_98_dialog_content = "Recientemente escuché un dicho famoso: \"¡El arte es una explosión!\"",
  ui_story_31110601_99_dialog_content = "¿Ah?",
  ui_story_31110601_100_dialog_content = "Si volamos el castillo de arena, ¡el resultado podría parecer incluso fuegos artificiales!",
  ui_story_31110601_101_dialog_content = "La vista de la explosión quedará grabada en nuestras mentes, convirtiéndose en un recuerdo inolvidable.",
  ui_story_31110601_X101_dialog_content = "En cierto modo, ¡el castillo de arena también nacerá de nuevo!",
  ui_story_31110601_102_dialog_content = "¡Imagínalo! Beryl, sonriendo mientras las arenas rosadas llueven a su alrededor...",
  ui_story_31110601_X102_dialog_content = "¡Ahh, qué hermosa escena!",
  ui_story_31110601_103_dialog_content = "Por cierto, mientras mi Cartucho de Agua Bendita esté enterrada en los cimientos del castillo, estoy seguro de que la explosión hara la escena a la perfección.",
  ui_story_31110601_104_dialog_content = "¿Entonces, qué piensas? Es una gran idea, ¿verdad?",
  ui_story_31110601_105_dialog_content = "......",
  ui_story_31110601_106_dialog_content = "¡Oye! ¡Bájame, PlayerName! ¡No puedo alcanzar el suelo!",
  ui_story_31110601_107_dialog_content = "¿Qué clase de maldad se ha estado cocinando en esa cabeza tuya hoy?",
  ui_story_31110601_108_dialog_content = "¿No sabes cómo había estado trabajando Beryl en ese castillo de arena? ¡¿Cómo pudiste siquiera pensar en volarlo?!",
  ui_story_31110601_109_dialog_content = "¡Oh, fue solo una sugerencia! ¡Realmente no estaba planeando volarlo!",
  ui_story_31110601_110_dialog_content = "Supongo que llevar el castillo de arena con nosotros está fuera de discusión...",
  ui_story_31110601_111_dialog_content = "Sip.",
  ui_story_31110601_112_dialog_content = "El estrés empieza a hacerme llorar...",
  ui_story_31110601_113_dialog_content = "¡Pero espera, no estoy llorando en absoluto! Entonces, ¿por qué corren lágrimas por mi rostro?",
  ui_story_31110601_114_dialog_content = "Creo... ¿Está lloviendo?",
  ui_story_31110601_115_dialog_content = "No esperaba que la lluvia llegara tan rápido...",
  ui_story_31110601_116_dialog_content = "Esculturas de arena de Beryl...",
  ui_story_31110601_117_dialog_content = "<color=#e8d9bb>La lluvia está derribando lentamente el castillo de arena.</color>",
  ui_story_31110601_118_dialog_content = "Necesitamos encontrar algo para bloquear la lluvia, o de lo contrario va a...",
  ui_story_31110601_119_dialog_content = "No pasa nada, PlayerName.",
  ui_story_31110601_X103_dialog_content = "Entiendo completamente.",
  ui_story_31110601_120_dialog_content = "Los castillos de arena no están destinados a durar para siempre. Aún así, están hechos de arena.",
  ui_story_31110601_121_dialog_content = "Si realmente quisiéramos hacer algo que pudiera durar para siempre, entonces <size=30>desde el principio...</size>",
  ui_story_31110601_122_dialog_content = "Debería haber elegido salir de otra cosa.",
  ui_story_31110601_123_dialog_content = "¿Estás bien, Beryl?",
  ui_story_31110601_124_dialog_content = "Hacer algo así de elaborado debe haber requerido toda tu paciencia y tu mente, ¿verdad?",
  ui_story_31110601_125_dialog_content = "Puedo otarlo, con solo mirar, puedo sentir tus sentimientos.",
  ui_story_31110601_126_dialog_content = "No estoy molesto por eso. De lo contrario...",
  ui_story_31110601_X104_dialog_content = "De hecho, estoy bastante feliz.",
  ui_story_31110601_127_dialog_content = "¿No creen ustedes dos que es hermoso como es, incluso ahora?",
  ui_story_31110601_128_dialog_content = "Con el telón de fondo de un arco iris en el cielo nublado, la lluvia que cae parece lágrimas corriendo por el rostro de la doncella.",
  ui_story_31110601_130_dialog_content = "Si su existencia no fuera tan corta, nunca...",
  ui_story_31110601_131_dialog_content = "Ella nunca estaría tan llena de vida, aquí en este momento.",
  ui_story_31110601_132_dialog_content = "Es como esas escenas románticas representadas en los libros que hemos leído.",
  ui_story_31110601_133_dialog_content = "...¿Así que todavía te gusta a pesar de que está mojado, Beryl?",
  ui_story_31110601_134_dialog_content = "Solo creo que tal vez... Ya no tiene sentido preocuparse por cómo llevárselo con nosotros.",
  ui_story_31110601_135_dialog_content = "Dejarlo aquí tampoco es mala idea... tal vez alguien más pueda verlo también.",
  ui_story_31110601_136_dialog_content = "Realmente has cambiado mucho, Beryl.",
  ui_story_31110601_137_dialog_content = "Te has vuelto mucho más alegre, alguien que ha aprendido a dejar ir las cosas.",
  ui_story_31110601_138_dialog_content = "Todo es gracias a ustedes...",
  ui_story_31110601_139_dialog_content = "Dejé de preocuparme por el pasado. Ya no le tengo miedo a mis recuerdos.",
  ui_story_31110601_140_dialog_content = "<color=#e8d9bb>Beryl sonrió, y no era de esos cautelosos e inseguros que solía tener...</color>",
  ui_story_31110601_141_dialog_content = "<color=#e8d9bb>Fue una sonrisa alegre y contagiosa, una que nos hizo hacer lo mismo sin que nos diéramos cuenta.</color>",
  ui_story_31110601_142_dialog_content = "Así que ahora, no siento que separarse sea algo tan malo.",
  ui_story_31110601_143_dialog_content = "¿Separarse...?",
  ui_story_31110601_144_dialog_content = "Eso es correcto. Todos irán por caminos separados esta noche.",
  ui_story_31110601_145_dialog_content = "Así que no solo nos despediremos de tu castillo de arena, sino también de ti, Beryl...",
  ui_story_31110601_146_dialog_content = "¡No te preocupes, Raphaela! Yo... ¡te prometo que iré a visitarte a Lumopolis!",
  ui_story_31110601_147_dialog_content = "¡Oh, Beryl!",
  ui_story_31110601_148_dialog_content = "Aunque nos separemos, ¡no es como si no nos volviéramos a ver! Crearemos nuevos recuerdos en el futuro, ¿de acuerdo?",
  ui_story_31110601_149_dialog_content = "El año que viene y el año siguiente, y todos los años siguientes...",
  ui_story_31110601_150_dialog_content = "Con Raphaela... y tú, PlayerName.",
  ui_story_31110601_151_dialog_content = "<color=#e8d9bb>Al decir esto, Beryl volvió a bajar la cabeza con torpeza.</color>",
  ui_story_31110601_152_dialog_content = "PlayerName...",
  ui_story_31110601_153_dialog_content = "Vendrás a jugar a la playa conmigo de nuevo el año que viene... ¿verdad?",
  ui_story_31110601_154_option_content = "Absolutamente."
}
return config
